CREATE FUNCTION pg_temp.c19() RETURNS text LANGUAGE plpgsql AS $qq$
DECLARE
  r text;
  cname text := $q$server writers keep the columns they set (service_role insert; definer insert called by a client)$q$;
  a uuid; b uuid; c uuid; i uuid; n uuid; x uuid; y uuid;
  t text; t2 text; e text; st text; ok boolean; j jsonb; j2 jsonb; k int;
