    'INSERT INTO public.users (id, email, oauth_provider, oauth_id, status, provisioning_source, is_managed, jit_provisioned)
     VALUES (p, ''c19-3998-def@example.test'', ''google'', ''c19-3998-def'', ''suspended'', ''jit'', true, true)'$d$;
  y := gen_random_uuid();
