  ok := t = 'suspended,scim,c19-ext,t,t,t,enterprise,c19-3998-ext'
    AND t2 = 'suspended,jit,t,t,c19-3998-def';
  r := pg_temp.res(ok, 'C19 ' || cname, t || ' | ' || t2);

    RAISE EXCEPTION USING ERRCODE = 'ZX998', MESSAGE = r;
